package live.linghe.privateinput;
import java.util.*;
public final class LearningDeltaIndexTest {
 static int checks;static void ok(boolean value,String label){++checks;if(!value)throw new AssertionError(label);}
 interface Work{void run()throws Exception;}static void rejects(Work work,String label)throws Exception{boolean bad=false;try{work.run();}catch(Exception expected){bad=true;}ok(bad,label);}
 public static void main(String[]args)throws Exception{
  Map<String,String> rows=new TreeMap<>(),personal=new TreeMap<>();for(int i=0;i<3000;i++)rows.put("ce shi\u001f合成词"+i,"{\"reading\":\"ce shi\",\"text\":\"合成词"+i+"\",\"count\":1}");for(int i=0;i<500;i++)personal.put("id-"+i,"{\"version\":1,\"record\":"+i+"}");
  LearningDeltaIndex.Prepared initial=LearningDeltaIndex.prepare("group/1",rows,personal,null,1000,false);ok(initial.full&&initial.entries.size()==3000&&initial.personal.size()==500,"bootstrap includes complete rows");ok(initial.checkpoint.fullRepairAt==1000,"bootstrap establishes repair time");
  LearningDeltaIndex.Prepared unchanged=LearningDeltaIndex.prepare("group/1",rows,personal,initial.checkpoint,1600,false);ok(!unchanged.full&&!unchanged.hasPayload(),"unchanged model emits nothing");
  rows.put("ce shi\u001f合成词5","{\"reading\":\"ce shi\",\"text\":\"合成词5\",\"count\":2}");LearningDeltaIndex.Prepared changed=LearningDeltaIndex.prepare("group/1",rows,personal,initial.checkpoint,1600,false);ok(!changed.full&&changed.entries.size()==1&&changed.personal==null,"one choice transmits one complete CRDT row");ok(changed.checkpoint.fullRepairAt==1000,"ordinary delta never refreshes repair clock");
  int allBytes=0,deltaBytes=0;for(String value:rows.values())allBytes+=value.getBytes(java.nio.charset.StandardCharsets.UTF_8).length;for(String value:changed.entries.values())deltaBytes+=value.getBytes(java.nio.charset.StandardCharsets.UTF_8).length;ok(deltaBytes<allBytes/100,"small edit has bounded subset bytes");
  personal.put("id-3","{\"version\":2,\"deleted\":true}");LearningDeltaIndex.Prepared personalChange=LearningDeltaIndex.prepare("group/1",rows,personal,changed.checkpoint,2200,false);ok(personalChange.entries.isEmpty()&&personalChange.personal.size()==1,"personal tombstone uses UUID record subset");ok(personalChange.checkpoint.fullRepairAt==1000,"personal delta does not refresh repair time");
  rows.put("ce shi\u001f合成词6","{\"generation\":1,\"deleted\":true,\"counts\":{\"replica\":9}}");LearningDeltaIndex.Prepared tombstone=LearningDeltaIndex.prepare("group/1",rows,personal,personalChange.checkpoint,2800,false);ok(tombstone.entries.size()==1&&tombstone.entries.values().iterator().next().contains("\"deleted\":true"),"deletion retains complete semantic control");
  LearningDeltaIndex.Checkpoint checkpoint=tombstone.checkpoint;for(long now=3400;now<87400;now+=600){LearningDeltaIndex.Prepared step=LearningDeltaIndex.prepare("group/1",rows,personal,checkpoint,now,false);ok(!step.full&&step.checkpoint.fullRepairAt==1000,"ten-minute maintenance cannot postpone daily full repair");checkpoint=step.checkpoint;}
  LearningDeltaIndex.Prepared repair=LearningDeltaIndex.prepare("group/1",rows,personal,checkpoint,87400,false);ok(repair.full&&repair.entries.size()==3000&&repair.personal.size()==500&&repair.checkpoint.fullRepairAt==87400,"daily repair runs despite frequent deltas");
  ok(LearningDeltaIndex.prepare("group/2",rows,personal,repair.checkpoint,88000,false).full,"new epoch bootstraps");ok(LearningDeltaIndex.prepare("other/2",rows,personal,repair.checkpoint,88000,false).full,"new group bootstraps");ok(LearningDeltaIndex.prepare("group/1",rows,personal,repair.checkpoint,88000,true).full,"expired pending envelope forces repair");ok(LearningDeltaIndex.prepare("group/1",rows,personal,repair.checkpoint,100,false).full,"wall clock rollback forces repair");
  Map<String,String> missing=new TreeMap<>(rows);missing.remove("ce shi\u001f合成词5");rejects(()->LearningDeltaIndex.prepare("group/1",missing,personal,repair.checkpoint,88000,false),"silent row disappearance is not a deletion");Map<String,String> missingPersonal=new TreeMap<>(personal);missingPersonal.remove("id-3");rejects(()->LearningDeltaIndex.prepare("group/1",rows,missingPersonal,repair.checkpoint,88000,false),"personal tombstone cannot disappear silently");
  ok(LearningDeltaIndex.prepare("empty/1",Collections.emptyMap(),null,null,0,false).hasPayload(),"empty bootstrap still publishes a repair envelope");
  Map<String,String> reversed=new LinkedHashMap<>();List<String> keys=new ArrayList<>(rows.keySet());Collections.reverse(keys);for(String key:keys)reversed.put(key,rows.get(key));ok(!LearningDeltaIndex.prepare("group/1",reversed,personal,repair.checkpoint,88000,false).hasPayload(),"map enumeration order cannot cause updates");
  System.out.println("PASS "+checks+" learning delta index checks; syntheticFullBytes="+allBytes+" syntheticDeltaBytes="+deltaBytes+" network=false");
 }
}
